#!/usr/bin/env bash
# PreToolUse hook: EF Core migrations are append-only.
# Blocks Edit/Write of a migration file (Migrations/*.cs, incl. *.Designer.cs) that is already
# tracked by git. The model snapshot (*ModelSnapshot.cs) is regenerated by EF and stays editable;
# creating new migration files is allowed.
# Exit 2 = block the tool call; stderr is shown to Claude.
set -u

input="$(cat)"
command -v jq >/dev/null 2>&1 || exit 0

file="$(printf '%s' "$input" | jq -r '.tool_input.file_path // empty')"
[[ -n "$file" ]] || exit 0
[[ "$file" == */Migrations/*.cs ]] || exit 0
[[ "$file" == *ModelSnapshot.cs ]] && exit 0

cd "${CLAUDE_PROJECT_DIR:-.}" || exit 0
rel="$(realpath --relative-to=. "$file" 2>/dev/null || printf '%s' "$file")"

if git ls-files --error-unmatch -- "$rel" >/dev/null 2>&1; then
  echo "Migration '$rel' is already committed. EF Core migrations are append-only: change the model and add a new migration (dotnet ef migrations add <Name> --project src/TaskFlow.Persistence) instead of editing this one." >&2
  exit 2
fi

exit 0
